import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, mul, float } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry (tessellated)
  const geometry = new PlaneGeometry(1, 1, 64, 64);
  geometry.rotateX(-Math.PI / 2); // make it face upward by default (optional)

  // Basic NodeMaterial placeholder
  const material = new MeshStandardNodeMaterial({ color: 0xffffff, transparent: true });

  // Mesh
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load textures asynchronously (function stays synchronous)
  let colorTexture, depthTexture;
  const colorPromise = config.imageUrl
    ? ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
        colorTexture = tex;
        const colorNode = texture(tex);
        material.colorNode = colorNode;
        material.needsUpdate = true;
      })
    : Promise.resolve();

  const depthPromise = config.depthMapUrl
    ? ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
        depthTexture = tex;
        const depthNode = texture(tex);
        // Displace using red channel scaled modestly
        material.displacementNode = mul(depthNode.r, float(0.15));
        material.displacementScale = 1.0; // fallback for non‑node pipelines
        material.needsUpdate = true;
      })
    : Promise.resolve();

  // Ensure any texture load errors do not break the node
  Promise.all([colorPromise, depthPromise]).catch(() => { /* silent */ });

  // Interaction: hover lift (rise‑in) and click emit
  const hoverTL = gsap.timeline({ paused: true });
  hoverTL.to(
    plane.position,
    {
      y: plane.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    },
  );

  // Store handlers in userData
  root.userData.handlers = {
    hover: (isHover) => {
      if (isHover) hoverTL.play(0);
      else hoverTL.reverse();
    },
    click: () => {
      ctx.emit('hub-features.select');
    },
  };

  // Apply parallax primitive (if available)
  let parallaxPrimitive = null;
  if (ctx.primitives && typeof ctx.primitives['parallax-scroll'] === 'function') {
    parallaxPrimitive = ctx.primitives['parallax-scroll'](plane, {});
  }

  // Cleanup routine
  root.userData.cleanup = () => {
    hoverTL.kill();
    if (parallaxPrimitive && typeof parallaxPrimitive.cleanup === 'function') {
      parallaxPrimitive.cleanup();
    }
    if (geometry) geometry.dispose();
    if (material) material.dispose();
    if (colorTexture) colorTexture.dispose();
    if (depthTexture) depthTexture.dispose();
  };

  return root;
}
